@Override public Account getAccountByKey(final String key,final InternalTenantContext context) throws AccountApiException {
  final AccountModelDao accountModelDao=accountDao.getAccountByKey(key,context);
  if (accountModelDao == null) {
    throw new AccountApiException(ErrorCode.ACCOUNT_DOES_NOT_EXIST_FOR_KEY,key);
  }
  return new DefaultAccount(accountModelDao);
}
